-- ============================================
-- LUMA — Thème 1 (Restaurant) : les 3 scénarios COURTS x4
-- ============================================


update scenarios set content = '{"characters": {"waiter": "le serveur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "waiter", "text": "Good evening! Table for one?", "text_fr": "Bonsoir ! Une table pour une personne ?", "choices": [{"text": "Yes, that''s right.", "text_fr": "Oui, c''est ça.", "next": "n2"}, {"text": "Actually, I''d like to sit at the bar instead.", "text_fr": "En fait, j''aimerais m''asseoir au bar plutôt.", "next": "n2b"}]}, "n2": {"speaker": "waiter", "text": "Right this way. Here''s the menu, can I get you something to drink?", "text_fr": "Par ici. Voici le menu, je vous sers quelque chose à boire ?", "choices": [{"text": "Just water, please.", "text_fr": "Juste de l''eau, s''il vous plaît.", "next": "n3"}, {"text": "A lemonade, please.", "text_fr": "Une limonade, s''il vous plaît.", "next": "n3"}]}, "n2b": {"speaker": "waiter", "text": "Of course, right this way to the bar. Something to drink?", "text_fr": "Bien sûr, par ici pour le bar. Quelque chose à boire ?", "choices": [{"text": "Just water, please.", "text_fr": "Juste de l''eau, s''il vous plaît.", "next": "n3"}, {"text": "A lemonade, please.", "text_fr": "Une limonade, s''il vous plaît.", "next": "n3"}]}, "n3": {"speaker": "waiter", "text": "Great, I''ll bring that right away. Have you decided on your meal?", "text_fr": "Parfait, j''apporte ça tout de suite. Vous avez choisi votre plat ?", "choices": [{"text": "Not yet, could you recommend something?", "text_fr": "Pas encore, vous pourriez me recommander quelque chose ?", "next": "n4"}, {"text": "Yes, I''ll have the grilled chicken.", "text_fr": "Oui, je vais prendre le poulet grillé.", "next": "n4b"}, {"text": "What''s today''s special?", "text_fr": "Quel est le plat du jour ?", "next": "n4c"}]}, "n4": {"speaker": "waiter", "text": "The salmon is very popular tonight, it comes with seasonal vegetables.", "text_fr": "Le saumon est très demandé ce soir, il est servi avec des légumes de saison.", "choices": [{"text": "That sounds perfect, I''ll take it.", "text_fr": "Ça a l''air parfait, je le prends.", "next": "n5"}, {"text": "Actually, I''ll go with the pasta instead.", "text_fr": "En fait, je vais prendre les pâtes plutôt.", "next": "n5"}]}, "n4b": {"speaker": "waiter", "text": "Excellent choice. Any sides with that?", "text_fr": "Excellent choix. Un accompagnement avec ça ?", "choices": [{"text": "Fries, please.", "text_fr": "Des frites, s''il vous plaît.", "next": "n5"}, {"text": "A side salad, please.", "text_fr": "Une salade en accompagnement, s''il vous plaît.", "next": "n5"}]}, "n4c": {"speaker": "waiter", "text": "Tonight it''s a mushroom risotto, made fresh.", "text_fr": "Ce soir c''est un risotto aux champignons, fait maison.", "choices": [{"text": "I''ll try that, thank you.", "text_fr": "Je vais essayer ça, merci.", "next": "n5"}, {"text": "I think I''ll stick with something simpler.", "text_fr": "Je pense que je vais rester sur quelque chose de plus simple.", "next": "n4b"}]}, "n5": {"speaker": "waiter", "text": "Great choice! I''ll get that started for you.", "text_fr": "Excellent choix ! Je lance ça pour vous.", "choices": [{"text": "Thank you very much.", "text_fr": "Merci beaucoup.", "next": "n6"}, {"text": "How long will it take, roughly?", "text_fr": "Ça prendra combien de temps, environ ?", "next": "n6b"}]}, "n6": {"speaker": "waiter", "text": "You''re welcome, it''ll be about fifteen minutes.", "text_fr": "Je vous en prie, ce sera environ quinze minutes.", "choices": [{"text": "Perfect, no rush.", "text_fr": "Parfait, aucune urgence.", "next": "end_relaxed"}]}, "n6b": {"speaker": "waiter", "text": "About fifteen minutes, is that alright?", "text_fr": "Environ quinze minutes, ça vous convient ?", "choices": [{"text": "Perfect, no rush.", "text_fr": "Parfait, aucune urgence.", "next": "end_relaxed"}, {"text": "That works, I have some time.", "text_fr": "Ça marche, j''ai du temps.", "next": "end_relaxed"}]}, "end_relaxed": {"speaker": "waiter", "text": "Wonderful. Enjoy your evening!", "text_fr": "Merveilleux. Bonne soirée !", "end": true, "ending_label": "Commande passée avec assurance 🍽️"}}}'::jsonb, is_playable = true
where title = 'Commander un plat simple'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));


update scenarios set content = '{"characters": {"waiter": "le serveur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "waiter", "text": "Welcome! Are you ready to order, or do you have any questions?", "text_fr": "Bienvenue ! Vous êtes prêt à commander, ou avez-vous des questions ?", "choices": [{"text": "Actually, I have a nut allergy — I need to ask about a few dishes.", "text_fr": "En fait, j''ai une allergie aux fruits à coque — je dois me renseigner sur quelques plats.", "next": "n2"}, {"text": "Yes, but first — does the kitchen handle allergies carefully?", "text_fr": "Oui, mais d''abord — la cuisine gère-t-elle bien les allergies ?", "next": "n2b"}]}, "n2": {"speaker": "waiter", "text": "Thank you for letting me know. Which dish were you considering?", "text_fr": "Merci de me le signaler. Quel plat envisagiez-vous ?", "choices": [{"text": "The pad thai — does it contain peanuts?", "text_fr": "Le pad thaï — il contient des cacahuètes ?", "next": "n3"}, {"text": "The pesto pasta — is there pine nuts in the sauce?", "text_fr": "Les pâtes au pesto — il y a des pignons de pin dans la sauce ?", "next": "n3b"}]}, "n2b": {"speaker": "waiter", "text": "Absolutely, we take allergies very seriously here. What''s the allergy?", "text_fr": "Absolument, on prend les allergies très au sérieux ici. C''est quelle allergie ?", "choices": [{"text": "A nut allergy — tree nuts and peanuts both.", "text_fr": "Une allergie aux fruits à coque — noix et cacahuètes toutes les deux.", "next": "n3"}]}, "n3": {"speaker": "waiter", "text": "Yes, the pad thai does contain crushed peanuts, I''m afraid.", "text_fr": "Oui, le pad thaï contient bien des cacahuètes concassées, malheureusement.", "choices": [{"text": "Could you make it without the peanuts?", "text_fr": "Vous pourriez le faire sans les cacahuètes ?", "next": "n4"}, {"text": "I''ll choose something else then.", "text_fr": "Je vais choisir autre chose alors.", "next": "n4b"}]}, "n3b": {"speaker": "waiter", "text": "Let me check with the kitchen — one moment.", "text_fr": "Laissez-moi vérifier avec la cuisine — un instant.", "choices": [{"text": "Thank you, I appreciate it.", "text_fr": "Merci, j''apprécie.", "next": "n4c"}]}, "n4": {"speaker": "waiter", "text": "Let me check — yes, the chef can prepare it without any nuts.", "text_fr": "Laissez-moi vérifier — oui, le chef peut le préparer sans aucune noix.", "choices": [{"text": "That''s great, I''ll take that then.", "text_fr": "C''est parfait, je le prends alors.", "next": "n5"}]}, "n4b": {"speaker": "waiter", "text": "No problem at all. May I suggest the grilled chicken instead? It''s nut-free.", "text_fr": "Aucun problème. Puis-je suggérer le poulet grillé à la place ? Il est sans noix.", "choices": [{"text": "Perfect, I''ll have that.", "text_fr": "Parfait, je vais prendre ça.", "next": "n5"}]}, "n4c": {"speaker": "waiter", "text": "Good news — no pine nuts in our pesto, just basil, garlic and cheese.", "text_fr": "Bonne nouvelle — pas de pignons dans notre pesto, juste basilic, ail et fromage.", "choices": [{"text": "That''s a relief, I''ll have that then.", "text_fr": "C''est un soulagement, je vais prendre ça alors.", "next": "n5"}]}, "n5": {"speaker": "waiter", "text": "I''ll also flag this at the kitchen to be extra careful with cross-contamination.", "text_fr": "Je vais aussi le signaler en cuisine pour faire très attention à la contamination croisée.", "choices": [{"text": "Thank you, that means a lot.", "text_fr": "Merci, ça compte beaucoup.", "next": "n6"}, {"text": "I really appreciate the thoroughness.", "text_fr": "J''apprécie vraiment ce sérieux.", "next": "n6"}]}, "n6": {"speaker": "waiter", "text": "Of course, your safety comes first. I''ll bring it out shortly.", "text_fr": "Bien sûr, votre sécurité passe avant tout. Je vous apporte ça bientôt.", "choices": [{"text": "Thank you so much.", "text_fr": "Merci beaucoup.", "next": "end_safe"}]}, "end_safe": {"speaker": "waiter", "text": "You''re very welcome. Enjoy your meal safely!", "text_fr": "Je vous en prie. Bon appétit en toute sécurité !", "end": true, "ending_label": "Allergie gérée avec sérieux 🥜🚫"}}}'::jsonb, is_playable = true
where title = 'Une allergie à signaler'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
